/bin/zsh -lc "python3 -B -c 'import csv,json,re,collections,hashlib
from pathlib import Path
def read(f):
 with open(f,newline='\\'''\\'',encoding='\\''utf-8-sig'\\'') as h:return list(csv.DictReader(h))
def norm(v):return re.sub('\\''["'^A-Z0-9]'"'\\'','\\'''\\'',str(v or '\\'''\\'').upper())
def num(v):
 try:return str(int(float(v)))
 except (ValueError,OverflowError):return (v or '\\'''\\'').strip()
m=read('\\''data/Model.csv'\\'');s=read('\\''data/CRISPRScreenMap.csv'\\'');c=read('\\''lock_s/cohort.csv'\\'');p=read('\\''data/passports_model_list_20260921.csv'\\'')
idx=collections.defaultdict(list)
for r in p:
 for x in [r['\\''model_name'\\'']]+re.split('\\''[|;]'\\'',r['\\''synonyms'\\'']):
  if norm(x):idx[norm(x)].append(r)
res={};un=[];amb=[]
for r in c:
 pat={x['\\''patient_id'\\''] for x in idx[norm(r['\\''sample_ID'\\''])]}
 if len(pat)==1:res[r['\\''sample_ID'\\'']]=next(iter(pat))
 elif pat:amb.append((r['\\''sample_ID'\\''],sorted(pat)))
 else:un.append(r['\\''sample_ID'\\''])
cp=set(res.values());pc=[r for r in p if r['\\''patient_id'\\''] in cp]
artifact=json.loads(Path('\\''generations/sgen010/cohort_C_patient_map_v1.json'\\'').read_text())
print('\\''WITNESS'\\'',len(c),len(res),len(cp),'\\''unresolved'\\'',un,'\\''ambiguous'\\'',amb,'\\''map_equal'\\'',res==artifact['\\''sample_ID_to_SIDP'\\''],'\\''empty patient?'\\'', '\\'''\\'' in cp)
print('\\''UNIQUE/NULL'\\'', {name:{'\\''rows'\\'':len(rr),'\\''unique'\\'':len({r[col] for r in rr}),'\\''empty'\\'':sum(not r[col] for r in rr)} for name,rr,col in [('\\''ModelID'\\'',m,'\\''ModelID'\\''),('\\''ScreenID'\\'',s,'\\''ScreenID'\\''),('\\''cohort_sample'\\'',c,'\\''sample_ID'\\''),('\\''pp_Model'\\'',p,'\\''model_id'\\''),('\\''pp_Patient'\\'',p,'\\''patient_id'\\'')]})
screen={r['\\''ModelID'\\''] for r in s};byid={r['\\''ModelID'\\'']:r for r in m};ms=[r for r in m if r['\\''ModelID'\\''] in screen]
print('\\''CENSUS'\\'',len(m),len({r['\\''PatientID'\\''] for r in m}),len(s),len(screen),len(ms),len({r['\\''PatientID'\\''] for r in ms}), '\\''missing_screen_ids'\\'',sorted(screen-byid.keys()),'\\''missing_patient'\\'',sum(not r['\\''PatientID'\\''] for r in m))
print('\\''MODEL_TYPES'\\'',dict(collections.Counter(r['\\''ModelType'\\''] for r in ms)),'\\''GROWTH'\\'',dict(collections.Counter(r['\\''GrowthPattern'\\''] for r in ms)),'\\''DEPMAP_TYPES'\\'',dict(collections.Counter(r['\\''DepmapModelType'\\''] for r in ms)))
o=[r for r in ms if r['\\''ModelType'\\'']=='\\''Organoid'\\''];print('\\''ORGANOID'\\'',len(o),len({r['\\''PatientID'\\''] for r in o}))
for mc,ppc,fn in [('\\''ModelID'\\'','\\''BROAD_ID'\\'',str),('\\''SangerModelID'\\'','\\''model_id'\\'',str),('\\''COSMICID'\\'','\\''COSMIC_ID'\\'',num),('\\''CellLineName'\\'','\\''model_name'\\'',norm),('\\''HCMIID'\\'','\\''HCMI'\\'',str)]:
 a={fn(r[mc]) for r in m if r[mc]};b={fn(r[ppc]) for r in p if r[ppc]};cc={fn(r[ppc]) for r in pc if r[ppc]}
 print('\\''KEY_CENSUS'\\'',mc,ppc, '\\''DepMap populated/unique'\\'',sum(bool(r[mc]) for r in m),len(a),'\\''PP populated/unique'\\'',sum(bool(r[ppc]) for r in p),len(b),'\\''C populated/unique'\\'',sum(bool(r[ppc]) for r in pc),len(cc),'\\''global intersect'\\'',len(a&b),'\\''C intersect'\\'',len(a&cc),'\\''DM_examples'\\'',sorted(a)[:4],'\\''C_examples'\\'',sorted(cc)[:4])
names={norm(x) for r in pc for x in [r['\\''model_name'\\'']]+re.split('\\''[|;]'\\'',r['\\''synonyms'\\'']) if norm(x)}
sets={'\\''broad'\\'':{r['\\''BROAD_ID'\\''] for r in pc if r['\\''BROAD_ID'\\'']},'\\''sidm'\\'':{r['\\''model_id'\\''] for r in pc if r['\\''model_id'\\'']},'\\''cosmic'\\'':{num(r['\\''COSMIC_ID'\\'']) for r in pc if r['\\''COSMIC_ID'\\'']},'\\''names'\\'':names,'\\''hcmi'\\'':{r['\\''HCMI'\\''].strip() for r in pc if r['\\''HCMI'\\'']}}
hits={k:set() for k in sets}
for r in m:
 for k,test in [('\\''broad'\\'',r['\\''ModelID'\\''] in sets['\\''broad'\\'']),('\\''sidm'\\'',r['\\''SangerModelID'\\''] in sets['\\''sidm'\\'']),('\\''cosmic'\\'',bool(r['\\''COSMICID'\\'']) and num(r['\\''COSMICID'\\'']) in sets['\\''cosmic'\\'']),('\\''names'\\'',any(norm(r[x]) in names for x in ['\\''CellLineName'\\'','\\''StrippedCellLineName'\\''])),('\\''hcmi'\\'',r['\\''HCMIID'\\''] in sets['\\''hcmi'\\''])]:
  if test:hits[k].add(r['\\''ModelID'\\''])
print('\\''V3_INDEPENDENT_HITS'\\'',{k:sorted(v) for k,v in hits.items()},'\\''C key cardinalities'\\'',{k:len(v) for k,v in sets.items()})
# Full PP-to-DepMap crosswalk including aliases/other usable keys
pi=collections.defaultdict(set)
for r in p:
 tokens=[r[x] for x in ['\\''model_id'\\'','\\''sample_id'\\'','\\''BROAD_ID'\\'','\\''CCLE_ID'\\'','\\''RRID'\\'','\\''HCMI'\\'','\\''model_name'\\'']]+re.split('\\''[|;]'\\'',r['\\''synonyms'\\''])
 for tok in tokens:
  if norm(tok):pi[norm(tok)].add(r['\\''model_id'\\''])
 if r['\\''COSMIC_ID'\\'']:pi['\\''COSMIC:'\\''+num(r['\\''COSMIC_ID'\\''])].add(r['\\''model_id'\\''])
pb={r['\\''model_id'\\'']:r for r in p};dmpp={};routes=collections.Counter();examples=[]
dmcols=['\\''ModelID'\\'','\\''CellLineName'\\'','\\''StrippedCellLineName'\\'','\\''RRID'\\'','\\''CCLEName'\\'','\\''ModelIDAlias'\\'','\\''HCMIID'\\'','\\''SangerModelID'\\'']
for r in m:
 matches=set()
 for col in dmcols:
  toks=[r[col]]+re.split('\\''[|;,]'\\'',r[col])
  h=set().union(*(pi.get(norm(t),set()) for t in toks if norm(t)))
  if h:routes[col]+=1;matches|=h
 if r['\\''COSMICID'\\'']:matches |= pi.get('\\''COSMIC:'\\''+num(r['\\''COSMICID'\\'']),set())
 dmpp[r['\\''ModelID'\\'']]=matches
 if any(pb[k]['\\''patient_id'\\''] in cp for k in matches):examples.append({x:r[x] for x in ['\\''ModelID'\\'','\\''PatientID'\\'','\\''CellLineName'\\'','\\''ModelType'\\'']})
print('\\''EXTENDED_C_MATCHES'\\'',examples)
print('\\''EXTENDED_MAP_COVERAGE'\\'', '\\''all'\\'',sum(bool(dmpp[r['\\''ModelID'\\'']]) for r in m),'\\''screened'\\'',sum(bool(dmpp[r['\\''ModelID'\\'']]) for r in ms),'\\''screened_unmatched'\\'',sum(not dmpp[r['\\''ModelID'\\'']] for r in ms),'\\''organoid_unmatched'\\'',sum(not dmpp[r['\\''ModelID'\\'']] for r in o),'\\''routes'\\'',dict(routes))
ptopp=collections.defaultdict(set);pptopt=collections.defaultdict(set)
for r in m:
 pats={pb[k]['\\''patient_id'\\''] for k in dmpp[r['\\''ModelID'\\'']]}
 for pat in pats:ptopp[r['\\''PatientID'\\'']].add(pat);pptopt[pat].add(r['\\''PatientID'\\''])
badpt={k:sorted(v) for k,v in ptopp.items() if len(v)>1};badsidp={k:sorted(v) for k,v in pptopt.items() if len(v)>1}
print('\\''PATIENT_ALIAS'\\'', '\\''depmap_patient_to_many_sidp'\\'',len(badpt),'\\''sidp_to_many_depmap'\\'',len(badsidp),'\\''examples_sidp'\\'',list(badsidp.items())[:20],'\\''C_alias'\\'', {k:v for k,v in badsidp.items() if k in cp},'\\''examples_pt'\\'',list(badpt.items())[:10])
unmapped=[r for r in ms if not dmpp[r['\\''ModelID'\\'']]]
unpt={r['\\''PatientID'\\''] for r in unmapped}
print('\\''SCREENED_UNMAPPED_PATIENTS'\\'',len(unpt),'\\''of_which_no_patient_crosswalk'\\'',len(unpt-ptopp.keys()),'\\''unmapped_type_counts'\\'',dict(collections.Counter(r['\\''ModelType'\\''] for r in unmapped)))
print('\\''UNMAPPED_EXAMPLES'\\'',[{k:r[k] for k in ['\\''ModelID'\\'','\\''PatientID'\\'','\\''CellLineName'\\'','\\''SangerModelID'\\'','\\''HCMIID'\\'','\\''ModelType'\\'','\\''ModelIDAlias'\\'']} for r in unmapped[:15]])
'"

